CREATE OR REPLACE FUNCTION public.messaging_allowed(_permission text DEFAULT 'chat.view') RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND account_status='active') AND (public.has_role(auth.uid(),'super_admin') OR (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('employee','manager')) AND (_permission IN ('chat.view','chat.create') OR EXISTS(SELECT 1 FROM public.user_access_roles u JOIN public.access_roles r ON r.id=u.role_id WHERE u.user_id=auth.uid() AND _permission=ANY(r.permissions))))) $$;
GRANT EXECUTE ON FUNCTION public.messaging_allowed(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.can_chat_with(_other uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.messaging_allowed('chat.view') AND _other<>auth.uid() AND EXISTS(SELECT 1 FROM public.profiles p JOIN public.user_roles r ON r.user_id=p.id WHERE p.id=_other AND p.account_status='active' AND r.role IN ('employee','manager','super_admin')) AND (public.has_role(auth.uid(),'super_admin') OR public.has_role(_other,'super_admin') OR EXISTS(SELECT 1 FROM public.company_members a JOIN public.company_members b ON a.company_id=b.company_id JOIN public.companies c ON c.id=a.company_id AND c.is_active WHERE a.user_id=auth.uid() AND b.user_id=_other)) $$;
CREATE OR REPLACE FUNCTION public.chat_people() RETURNS TABLE(id uuid,full_name text,email text,avatar_url text,role text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.full_name,p.email,p.avatar_url,(SELECT r.role::text FROM public.user_roles r WHERE r.user_id=p.id ORDER BY CASE WHEN r.role='super_admin' THEN 0 ELSE 1 END LIMIT 1) FROM public.profiles p WHERE public.can_chat_with(p.id) ORDER BY p.full_name $$;
GRANT EXECUTE ON FUNCTION public.chat_people() TO authenticated;
CREATE TABLE public.chat_groups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),owner_id uuid NOT NULL DEFAULT auth.uid(),name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100),description text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.chat_groups TO authenticated; GRANT ALL ON public.chat_groups TO service_role;
ALTER TABLE public.chat_groups ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.chat_group_members(group_id uuid NOT NULL REFERENCES public.chat_groups(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id),joined_at timestamptz NOT NULL DEFAULT now(),read_at timestamptz,PRIMARY KEY(group_id,user_id));
GRANT SELECT ON public.chat_group_members TO authenticated; GRANT ALL ON public.chat_group_members TO service_role;
ALTER TABLE public.chat_group_members ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.chat_group_access(_group uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.messaging_allowed('chat.view') AND EXISTS(SELECT 1 FROM public.chat_group_members m JOIN public.chat_groups g ON g.id=m.group_id JOIN public.companies c ON c.id=g.company_id AND c.is_active WHERE m.group_id=_group AND m.user_id=auth.uid() AND (public.has_role(auth.uid(),'super_admin') OR public.is_company_member(auth.uid(),g.company_id))) $$;
GRANT EXECUTE ON FUNCTION public.chat_group_access(uuid) TO authenticated;
CREATE POLICY "Group participants read" ON public.chat_groups FOR SELECT TO authenticated USING(public.chat_group_access(id));
CREATE POLICY "Group members read" ON public.chat_group_members FOR SELECT TO authenticated USING(public.chat_group_access(group_id));
ALTER TABLE public.chat_messages ADD COLUMN group_id uuid REFERENCES public.chat_groups(id), ADD COLUMN client_id uuid;
CREATE UNIQUE INDEX chat_message_retry_key ON public.chat_messages(sender_id,client_id) WHERE client_id IS NOT NULL;
CREATE INDEX chat_group_history_idx ON public.chat_messages(group_id,created_at);
CREATE POLICY "Active chat scope" ON public.chat_messages AS RESTRICTIVE FOR ALL TO authenticated USING(public.messaging_allowed('chat.view') AND CASE WHEN group_id IS NOT NULL THEN public.chat_group_access(group_id) ELSE (sender_id=auth.uid() OR recipient_id=auth.uid()) AND public.can_chat_with(CASE WHEN sender_id=auth.uid() THEN recipient_id ELSE sender_id END) END) WITH CHECK(public.messaging_allowed('chat.create') AND sender_id=auth.uid() AND CASE WHEN group_id IS NOT NULL THEN public.chat_group_access(group_id) ELSE public.can_chat_with(recipient_id) END);
CREATE POLICY "Group history read" ON public.chat_messages FOR SELECT TO authenticated USING(group_id IS NOT NULL AND public.chat_group_access(group_id));
REVOKE UPDATE ON public.chat_messages FROM authenticated; GRANT UPDATE(read_at) ON public.chat_messages TO authenticated;
CREATE OR REPLACE FUNCTION public.chat_group_action(_action text,_payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE gid uuid; g public.chat_groups; uid uuid; cid uuid; BEGIN
IF NOT public.messaging_allowed('chat.create') THEN RAISE EXCEPTION 'Messaging access denied'; END IF;
IF _action='create' THEN cid:=(_payload->>'company_id')::uuid; IF NOT EXISTS(SELECT 1 FROM public.companies WHERE id=cid AND is_active) OR NOT(public.has_role(auth.uid(),'super_admin') OR public.is_company_member(auth.uid(),cid)) THEN RAISE EXCEPTION 'Company access denied'; END IF; INSERT INTO public.chat_groups(company_id,name,description) VALUES(cid,trim(_payload->>'name'),left(coalesce(_payload->>'description',''),1000)) RETURNING id INTO gid; INSERT INTO public.chat_group_members(group_id,user_id) VALUES(gid,auth.uid());
FOR uid IN SELECT value::uuid FROM jsonb_array_elements_text(coalesce(_payload->'members','[]')) LOOP IF NOT public.can_chat_with(uid) OR NOT(public.has_role(uid,'super_admin') OR public.is_company_member(uid,cid)) THEN RAISE EXCEPTION 'Member not authorized'; END IF; INSERT INTO public.chat_group_members VALUES(gid,uid,now(),null) ON CONFLICT DO NOTHING; END LOOP; RETURN gid; END IF;
gid:=(_payload->>'id')::uuid; SELECT * INTO g FROM public.chat_groups WHERE id=gid FOR UPDATE; IF NOT FOUND OR NOT public.chat_group_access(gid) THEN RAISE EXCEPTION 'Group access denied'; END IF;
IF _action='read' THEN UPDATE public.chat_group_members SET read_at=now() WHERE group_id=gid AND user_id=auth.uid(); RETURN gid; END IF;
IF _action='exit' THEN IF g.owner_id=auth.uid() THEN RAISE EXCEPTION 'Group owner must retain membership'; END IF; DELETE FROM public.chat_group_members WHERE group_id=gid AND user_id=auth.uid(); RETURN gid; END IF;
IF g.owner_id<>auth.uid() THEN RAISE EXCEPTION 'Group owner access required'; END IF; uid:=(_payload->>'user_id')::uuid;
IF _action='add' THEN IF NOT public.can_chat_with(uid) OR NOT(public.has_role(uid,'super_admin') OR public.is_company_member(uid,g.company_id)) THEN RAISE EXCEPTION 'Member not authorized'; END IF; INSERT INTO public.chat_group_members VALUES(gid,uid,now(),null) ON CONFLICT DO NOTHING;
ELSIF _action='remove' THEN IF uid=g.owner_id THEN RAISE EXCEPTION 'Owner cannot be removed'; END IF; DELETE FROM public.chat_group_members WHERE group_id=gid AND user_id=uid; ELSE RAISE EXCEPTION 'Unsupported action'; END IF; RETURN gid; END $$;
GRANT EXECUTE ON FUNCTION public.chat_group_action(text,jsonb) TO authenticated;
CREATE TABLE public.chat_attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),message_id uuid NOT NULL REFERENCES public.chat_messages(id) ON DELETE CASCADE,filename text NOT NULL,path text NOT NULL UNIQUE,mime text NOT NULL,size integer NOT NULL CHECK(size BETWEEN 1 AND 5242880),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.chat_attachments TO authenticated; GRANT ALL ON public.chat_attachments TO service_role;
ALTER TABLE public.chat_attachments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Participants read chat files" ON public.chat_attachments FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.chat_messages WHERE id=message_id));
CREATE POLICY "Sender records chat files" ON public.chat_attachments FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.chat_messages WHERE id=message_id AND sender_id=auth.uid()) AND path LIKE message_id::text||'/%');
ALTER PUBLICATION supabase_realtime ADD TABLE public.chat_groups,public.chat_group_members,public.chat_attachments;
ALTER TABLE public.whatsapp_templates ADD COLUMN company_id uuid REFERENCES public.companies(id),ADD COLUMN created_by uuid DEFAULT auth.uid(),ADD COLUMN header_type text NOT NULL DEFAULT 'text',ADD COLUMN samples jsonb NOT NULL DEFAULT '{}';
ALTER TABLE public.whatsapp_conversations ADD COLUMN company_id uuid REFERENCES public.companies(id),ADD COLUMN assigned_to uuid REFERENCES public.profiles(id);
CREATE OR REPLACE FUNCTION public.template_scope(_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.messaging_allowed('template.view') AND (public.has_role(auth.uid(),'super_admin') OR (_company IS NOT NULL AND public.is_company_member(auth.uid(),_company))) $$;
GRANT EXECUTE ON FUNCTION public.template_scope(uuid) TO authenticated;
CREATE POLICY "Authorized templates read" ON public.whatsapp_templates FOR SELECT TO authenticated USING(public.template_scope(company_id) AND (status='approved' AND sync_status='synced' OR public.messaging_allowed('template.create') OR public.messaging_allowed('template.edit')));
CREATE POLICY "Authorized local template create" ON public.whatsapp_templates FOR INSERT TO authenticated WITH CHECK(public.template_scope(company_id) AND public.messaging_allowed('template.create') AND created_by=auth.uid() AND status='draft' AND sync_status='not_synced');
CREATE POLICY "Authorized local template edit" ON public.whatsapp_templates FOR UPDATE TO authenticated USING(public.template_scope(company_id) AND public.messaging_allowed('template.edit') AND status='draft' AND sync_status='not_synced') WITH CHECK(public.template_scope(company_id) AND status='draft' AND sync_status='not_synced');
CREATE POLICY "Authorized local template delete" ON public.whatsapp_templates FOR DELETE TO authenticated USING(public.template_scope(company_id) AND public.messaging_allowed('template.delete') AND status='draft' AND sync_status='not_synced');
CREATE OR REPLACE FUNCTION public.guard_local_template() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.role()='authenticated' THEN IF TG_OP='DELETE' THEN IF OLD.status<>'draft' OR OLD.sync_status<>'not_synced' THEN RAISE EXCEPTION 'Provider templates are read-only'; END IF; RETURN OLD; END IF; IF NEW.status<>'draft' OR NEW.sync_status<>'not_synced' THEN RAISE EXCEPTION 'Provider approval cannot be set locally'; END IF; IF TG_OP='UPDATE' AND (OLD.status<>'draft' OR OLD.sync_status<>'not_synced' OR NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.created_by IS DISTINCT FROM OLD.created_by) THEN RAISE EXCEPTION 'Template identity and provider records are immutable'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER local_template_guard BEFORE INSERT OR UPDATE OR DELETE ON public.whatsapp_templates FOR EACH ROW EXECUTE FUNCTION public.guard_local_template();
CREATE POLICY "Assigned WhatsApp history" ON public.whatsapp_conversations FOR SELECT TO authenticated USING(public.messaging_allowed('whatsapp.view') AND company_id IS NOT NULL AND public.is_company_member(auth.uid(),company_id) AND assigned_to=auth.uid());
CREATE POLICY "Assigned WhatsApp messages" ON public.whatsapp_messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.whatsapp_conversations WHERE id=conversation_id));